const SECRET = process.env.JWT_SECRET;
if (!SECRET || Buffer.byteLength(SECRET) < 32) {
  throw new Error('JWT_SECRET missing or too short');
}

function requireAuth(req, res, next) {
  const m = /^Bearer ([\w-]+\.[\w-]+\.[\w-]+)$/i.exec(req.headers['authorization'] || '');
  try {
    if (!m) throw new Error('no bearer token');
    const payload = jwt.verify(m[1], SECRET, {
      algorithms: ['HS256'],
      issuer: 'your-issuer',
      audience: 'your-api',
      maxAge: '15m',
    });
    if (typeof payload !== 'object' || typeof payload.sub !== 'string' || typeof payload.exp !== 'number') {
      throw new Error('bad payload');
    }
    req.user = payload;
  } catch {
    return res.status(401).set('WWW-Authenticate', 'Bearer').json({ error: 'unauthorized' });
  }
  next();
}

module.exports = { requireAuth };
